	print("Grade C")
elif (marks >= 80):
	print("Grade A")

short.questionUr:
اس شرط میں منطقی غلطی (Logic Error) بتائیں:
marks = 85
if (marks >= 50):
	print("Grade C")
elif (marks >= 80):
	print("Grade A")
